\label{thm:ergodicthm}
For all $r>4$, there exists a constant $C>0$ such that the following holds. Let $(X,\mathcal{F},\mu)$ be a $\sigma$-finite measure space,  $T_0,T_1,T_2\colon~X\to X$   mutually commuting measure preserving transformations and let $J$ and $n_0<n_1<\cdots<n_J$ be positive integers. For any   $f_0,f_1\in L^8(X)$ and $f_2 \in L^4(X)$,  each of respective norms one,  we have the bound
\begin{equation*}

\sum_{j=1}^{J} \|M_{n_j}(f_0,f_1,f_2) - M_{n_{j-1}}(f_0,f_1,f_2)\|_{{L}^2(X)}^r \leq C ,
\end{equation*}
where we have defined for almost every $x\in X$ 
\begin{equation*}
M_{n}(f_0,f_1,f_2)(x) := \frac{1}{n}\sum_{i=0}^{n-1} f_0(T_0^i x) f_1(T_1^i x) f_2(T_2^i x).
\end{equation*}

\begin{equation*}
M_{n}(f_0,f_1,f_2)(x) := \frac{1}{n}\sum_{i=0}^{n-1} f_0(T_0^i x) f_1(T_1^i x) f_2(T_2^i x).
\end{equation*}

\label{thm:2}
For all $r>4$, there exists a  constant $C>0$ such that the following holds. For any positive integer $J$ and positive real numbers $t_0<t_1<\cdots < t_J$,  any $f_0,f_1\in L^8({\mathbb R}^3)$  and $f_2\in {L}^4(\mathbb{R}^3)$ with respective norms one, we have 
\begin{equation}\label{e:main2} \sum_{j=1}^{J} \|M_{t_j}(f_0,f_1,f_2) - M_{t_{j-1}}(f_0,f_1,f_2)\|_{{L}^2({\mathbb R}^3)}^r \leq C 
\end{equation}
where, with $e_0,e_1,e_2$ the standard unit vectors in ${\mathbb R}^3$, we have defined for almost every $x\in {\mathbb R}^3$:
\begin{equation}\label{eq:averages}
M_{t}(f_0,f_1,f_2)(x) := \frac{1}{t}\int_0^t f_0(x+\tau e_0) f_1(x+\tau e_1) f_2(x+\tau e_2)\,d\tau.
\end{equation}

\begin{equation}\label{eq:averages}
M_{t}(f_0,f_1,f_2)(x) := \frac{1}{t}\int_0^t f_0(x+\tau e_0) f_1(x+\tau e_1) f_2(x+\tau e_2)\,d\tau.
\end{equation}

Define 
\begin{equation}\label{defd1}
D_1:=(5,S, \Pi,(\Pi_s)_{s\in S})    
\end{equation}
 with 
$S=\{0,1,2\}\times \{0,1\}$, with $\Pi$ mapping ${\mathbb R}^5$ to ${\mathbb R}^2$ 
as
\[\Pi(x)=(x_3^0-x_0-x_1-x_2, x_3^1-x_0-x_1-x_2),\]
and with $\Pi_s$ for $s=(k,j)$ mapping ${\mathbb R}^5$ to ${\mathbb R}^3$ as
\[\Pi_{(k,j)}(x)=(x_0,x_1,x_2)-x_ke_k+ x_3^j e_k.\]

Each of the three following propositions will have a constant $C$, a 
parameter $J$ and formulate a class of kernels $K$ such that the 
singular Brascamp-Lieb estimate 
\begin{equation}\label{lambdabd}
|\Lambda_{D_1,K} ((f_s)_{s\in S})|\le CJ^{\frac 12}
\end{equation}
holds for all tuples of real-valued Schwartz functions $(f_{s})_{s\in S}$
such that
\begin{equation}\label{topbottom}
f_{(k,0)}=f_{(k,1)}
\end{equation}
for each $k\in \{0,1,2\}$
and 
\begin{equation}\label{normal1}
\|f_{(0,j)}\|_{8}=\|f_{(1,j)}\|_{8} =\|f_{(2,j)}\|_{4} =1
\end{equation}
for each $j\in \{0,1\}$.

Define for any function $\phi$ on ${\mathbb R}^d$ the $L^1$ normalized scaling
\begin{equation*}
\phi_{(t)}(x)=t^{-d} \phi(t^{-1}x).
\end{equation*}

\label{cor:1}
There exists a constant  $C>0$ such that the following holds. 
Let $J$ be a positive integer and   $(k_j)_{j=1}^J$ 
 a finite strictly monotone increasing sequence of integers. Let
\[K =\sum_{j=1}^J \phi_j\otimes \phi_j,\]
where for each $1\le j\le J$ we assume 
$\phi_j$ is a real-valued function on ${\mathbb R}$ with
\begin{equation*}
{\rm supp} (\widehat{\phi_j})\subset 
[-2^{-k_j+20},-2^{-k_j-20}]\cup [2^{-k_j-20},2^{-k_j+20}]
\end{equation*}  
and for all $u\in {\mathbb R}$,
\begin{equation*}
|(\phi_j)_{(2^{-k_j})}(u)| \leq  (1+|u|)^{-20}.
\end{equation*}

Then estimate \eqref{lambdabd} holds for any tuple as in \eqref{topbottom}, \eqref{normal1}.

\label{cor:2}
The variant of Proposition \ref{prop:2}, where
the assumption $k_j+10<l_j$ is replaced by the assumption $k_j<l_j$, holds.

 [Proved in Section \ref{sec:firstcz}] \label{firstcz} 
Let $\lambda=\frac{3}{2}$. There exists a constant $C>0$  such that the following holds for all $k\leq 0$. Let $J$ be a positive integer and let $(k_j)_{j=1}^J$ be a finite 
strictly increasing sequence of integers. Let $(\Phi_j)_{j=1}^J$ be a finite sequence of real valued functions on ${\mathbb R}^2$.
Assume that 
\[\textup{supp}(\widehat{\Phi_j}) \subseteq \{(\xi,\eta)\in {\mathbb R}^2 : 2^{-k_{j}-30}\leq |(\xi,\eta)| \leq 2^{-k_j+30} \}.  \]
Assume further that  for all $(u,v)\in {\mathbb R}^2$, 
\begin{equation}\label{E:phi-lambda3/2}
|(\Phi_j)_{(2^{-k_j})}(u,v)| \leq  2^{\lambda k}(1+2^k|u+v|)^{-4} (1+|u-v|)^{-4} 
+(1+|u+v|)^{-4} (1+|u-v|)^{-4}.
\end{equation}
Let $K$ be defined by
\[
K=\sum_{j=1}^J \Phi_{j}
\]
and assume that $\widehat{K}$ vanishes on the diagonal $\{(\xi,\eta)\in {\mathbb R}^2: \xi+\eta=0\}$.

Then estimate \eqref{lambdabd} holds for any tuple as in \eqref{topbottom}, \eqref{normal1}.

Define 
\begin{equation}\label{defd2}
    D_2:=(6,S, \Pi,(\Pi_s)_{s\in S})
\end{equation} with 
$S=\{0,1\}\times {\mathcal C}$,  where
${\mathcal C}$ is the set of functions $j:\{0,1\}\to \{0,1\}$,  with $\Pi$ mapping ${\mathbb R}^6$ to ${\mathbb R}^3$ as
\[\Pi(x) = (x_2^0-x_0-x_1-x_3^0, x_2^1-x_0-x_1-x_3^0, x_3^1-x_3^0),\]
and with $\Pi_s$ for $s=(k,j)$ mapping ${\mathbb R}^6$ to ${\mathbb R}^3$ as
\[\Pi_{(k,j)}(x)= (x_k, x_2^{j(0)}, x_3^{j(1)}). \]

For this datum $D_2$ and a kernel $K$, we are interested in a    loss free estimate 
\begin{equation}\label{lambdabd1}
|\Lambda_{D_2,K} ((f_s)_{s\in S})|\le C 
\end{equation}
for any tuple of real-valued Schwartz functions $(f_s)_{s\in S}$ with 
\begin{equation}\label{twosides}
f_{(k,j)}=f_{(k,j')} 
\end{equation}
for all $k\in\{0,1\}$ and $j,j'\in \mathcal{C}$, and
\begin{equation}\label{normal2}
\|f_{s}\|_{8}=1
\end{equation}
for all $s\in S$.

[Proved in Section \ref{sec:secstick}]
\label{secstickphi} 
 There is a constant $C$ such that the following holds. Let $J$ be a positive integer. 
For $1\le i\le 2$,  let  $(a_{i,j})_{j=1}^{J}$  be increasing sequences of positive real numbers. 


For $1\leq j \leq J$,  let $\rho_{j}:{\mathbb R}^4\to {\mathbb R}$ be a continuous function satisfying 

\begin{equation}\label{rhobound}
\int_{{\mathbb R}^2} |\rho_{j} | (u_1+p,u_2+p,u_3+r,u_4+r)\, dp dr
 \le a_{1,j}^{-1}(1+a_{1,j}^{-1}|u_1-u_2|)^{-2}
 a_{2,j}^{-1}(1+a_{2,j}^{-1}|u_3-u_4|)^{-2}
\end{equation}
for every $(u_1,u_2,u_3,u_4)\in {\mathbb R}^4$.
Let $(c_j)_{j=0}^J$ be an increasing sequence of positive {real} numbers,
well separated in that $2c_{j-1}\le c_j$ for $1\le j\le J$.
 Let $\chi$ be a left window.
For $1\le j\le J$ let $\phi_{j}:{\mathbb R}\to {\mathbb R}$ be   a continuous function, which exists due
 to the left window property of $\chi$, satisfying  $\widehat{\phi_j} \geq 0$  and 
 \[(\widehat{\phi_{j}})^2 = (\widehat{{\chi}_{(c_{j-1})}})^2 
 - (\widehat{{\chi}_{(c_j)}})^2. \]
 Let $K$ be defined by   
      \begin{equation}
        \label{ker1space}
    {K}(u,v,z)= \sum_{j=1}^J \int_{{\mathbb R}^3}{\phi_{j}}(p)
    {\phi_{j}}(q) {\rho_{j}}(u+p+q+r,v+p+q+r,z+r,r) \,dpdqdr. 
    \end{equation}

      Then estimate \eqref{lambdabd1} holds for any tuple as in \eqref{twosides}, \eqref{normal2}.

[Proved in Section \ref{sec:secstick}]
\label{secstickgauss}
 There is a constant $C$ such that the following holds. Let $J$ be a positive integer  and $(a_j)_{j=0}^J$, $(b_j)_{j=1}^J$  be increasing sequences of positive real numbers.    For $1\le j\le J$
 let $\phi_{j} :{\mathbb R}^2\to {\mathbb R}$ be a continuous function satisfying  
\begin{equation}\label{phistickgauss}
|\phi_{j}(u_1,u_2)| \leq (b_j)^{-2}(1+b_j^{-1}|(u_1, u_{2})|)^{-4} .  
\end{equation}
Let $K$ be a kernel such that
    \begin{equation}
        \label{ker2}
    \widehat{K}(\xi,\eta,\tau) =    \sum_{j=1}^J \int_{{a_{j-1}}}^{{a_{j}}}  t^2(\xi+\eta)^2 g(t\xi) g(t\eta)  \,\frac{dt}{t} \,
    \widehat{\phi_{j}}(\tau,-\xi-\eta-\tau).
    \end{equation}

    Then estimate \eqref{lambdabd1} holds for any tuple as in \eqref{twosides}, \eqref{normal2}.

We define
\begin{equation} \label{datumDA}
    D_A:=(6,S, \Pi,(\Pi_s)_{s\in S}),
\end{equation}
 where 
the projection 
$\Pi:{\mathbb R}^6\to {\mathbb R}^3$ is given by 
\begin{equation}
    \label{piT}
    \Pi(x)^T = (I,A) x^T,
\end{equation}
 where  $I$ is the $3\times 3$ identity matrix and $(I,A)$ is a $3 \times 6$ block matrix.

For  $\vartheta\in L^1({\mathbb R})$  we define in analogy with \eqref{eq:averages} for $x \in {\mathbb R}^3$
\begin{equation*}
M_{t}^\vartheta(f_0,f_1,f_2)(x) :=  \int_{{\mathbb R}} f_0(x+ue_0) f_1(x+ue_1) f_2(x+ue_2)\, \vartheta_{(t)}(u)\,du.
\end{equation*}

\label{L:lemmaDT}
For all $0<\varepsilon<1$, there exists a constant $C$ such that the following holds.

Let $A$ be a regular $3 \times 3$ matrix which differs from $-I$ by at most one row and   satisfies
\begin{equation}\label{E:assumption-A}
|\operatorname{det}A| >\varepsilon \quad \text{and} \quad
\|A\|_{HS} \leq \varepsilon^{-1},
\end{equation}
where $\|A\|_{HS}$ stands for the Hilbert-Schmidt norm of $A$. With $S$ as in the datum $D_A$, let $(f_s)_{s\in S}$ be a tuple of real-valued Schwartz functions such that $\|f_s\|_8=1$ for all $s\in S$. Let $i=1,2,3$ and let $K$ be the kernel satisfying
\begin{equation}\label{E:k-rewritten}
K(\Pi x)=
\int_0^\infty \int_{{\mathbb R}^3} (\partial_i\partial_{i+3} g)_{(t)}(x+((-Ap^T)^T,p))\,dp \frac{dt}{t}.
\end{equation} 
Then
\[
|\Lambda_{D_A,K}((f_s)_{s\in S})| \leq C. 
\]

Let $\lambda=\frac{3}{2}$. 
Let $k\le 0$ be given. Let an integer $J \geq 1$ and a strictly increasing sequence $(k_j)_{j=1}^J$ of integers be given. Let $(\Phi_j)_{j=1}^J$ and $K$ be given as in the proposition.
Let $(f_s)_{s\in S}$ be given as in~\eqref{topbottom} and~\eqref{normal1}.
Set $f_{k}:=f_{(k,0)}=f_{(k,1)}$ for each $k=0,1,2$.


Let $\theta: {\mathbb R} \rightarrow {\mathbb R}$ be a function whose Fourier transform is supported in   $[-2,-1/2] \cup [1/2,2]$ and whose derivatives up to order $8$ are $\lesssim 1$. Assume further that \[\int_0^\infty \widehat{\theta}(r\xi)\,\frac{dr}{r}=1\] for all $\xi \neq 0$.
We do the two parameter lacunary decomposition of $\widehat{K}$
in directions $\xi+\eta$ and $\xi-\eta$ and collect these pieces into  lacunary cones away from the line $\xi+\eta=0$ centered at the origin. In detail, we write
\begin{equation}\label{Kintos}
\widehat{K}(\xi,\eta)=\int_0^\infty \widehat{K^{(z)}} (\xi,\eta)\,\frac{dz}{z}
\end{equation}
with 
\begin{equation}\label{defKs}
\widehat{K^{(z)}}(\xi,\eta)=\int_0^\infty 
\widehat{K}(\xi,\eta) \widehat{\theta}(t(\xi-\eta)) \widehat{\theta}(z^{-1}t(\xi+\eta))
\,\frac{dt}{t}.
\end{equation}
We break the integral in \eqref{Kintos} into the integrals over the domains $(0,1)$ and $(1,\infty)$
and do the estimates for these integrals separately.  
We begin with the case $z\in (0,1)$. Here we do an estimate for each $z$ separately
and show for all $z< 1$ that
\begin{equation}\label{E:s-less-1}
|\Lambda_{D_1,K^{(z)}}((f_s)_{s\in S})| \lesssim z^{\frac{(\lambda-1)^2}{2\lambda}} J^{\frac{1}{2}},
\end{equation}
which is an integrable upper bound with respect to the measure $\frac{dz}{z}$. 
Fix $z\in (0,1)$.


Let $g$ be the one-dimensional Gaussian and let $h=g'$. Set $\widehat{\omega}=(\widehat{h})^{-1}\widehat{\theta}$. The function $\widehat{\omega}$ satisfies similar support and derivative estimates as $\widehat{\theta}$ since $\widehat{h}$ and its derivatives are essentially constant on the support of $\widehat{\theta}$.
In addition, let $\widehat{\phi}$ be a function
supported in the annulus $\frac{1}{16} \leq |(\xi,\eta)| \leq 16$
such that  its derivatives up to order $8$ are $\lesssim 1$ 
and  $\widehat{\phi}(\xi,\eta) \widehat{g}(\xi) \widehat{g}(\eta)=1$ if $1/8 \leq |(\xi,\eta)| \leq 8$.
Then, for all $\xi,\eta\in {\mathbb R}$,
\begin{equation}\label{E:gauss}
\widehat{\theta}(\xi-\eta) \widehat{\theta}(z^{-1}(\xi+\eta))
=
\widehat{\theta}(\xi-\eta)\widehat{\omega} (z^{-1}(\xi+\eta))
 \widehat{h}(z^{-1}(\xi+\eta))\widehat{\phi}(\xi,\eta) \widehat{g}(\xi) \widehat{g}(\eta). 
\end{equation}
 Note that this equality holds since the left-hand side is supported in the set where 
 \begin{equation}\label{E:support}
 1/8 \leq  |(\xi,\eta)| \leq 8.
 \end{equation} 
 Indeed, on the support of the left-hand side of~\eqref{E:gauss} we have
 $|\xi+\eta| \leq 2z \leq 2$ and $1/2 \leq |\xi-\eta| \leq 2$.
This yields~\eqref{E:support}. 

For $z\in (0,1)$ and $t>0$ we define the function $w^{z,t}$ via
\begin{equation}\label{E:def-wst}
\widehat{w^{z,t}}(\xi,\eta)= \widehat{K}(t^{-1}(\xi,\eta))\widehat{\phi}(\xi,\eta)\widehat{\theta}(\xi-\eta) \widehat{\omega} (z^{-1}(\xi+\eta)).
\end{equation}
Let $\Pi$ be the projection associated with the datum $D_1$. Using the Fourier inversion formula and equations \eqref{defKs}, \eqref{E:gauss} and~\eqref{E:def-wst}, we write ${K^{(z)}}(\Pi x)$ as
\begin{equation}\label{E:K_Pi}
\int_0^\infty \int_{{\mathbb R}^2}   \widehat{w^{z,t}}(t(\xi,\eta))
\widehat{h}(z^{-1}t(\xi+\eta))
\widehat{g}(t\xi) \widehat{g}(t\eta) 
e^{2\pi i( \xi (x_3^0-x_0-x_1-x_2)+\eta(x_3^1-x_0-x_1-x_2))}\,d\xi d\eta \frac{dt}{t}.
\end{equation}
Since the Fourier transform of $w^{z,t}$ is supported in the set where $\frac{1}{8} \leq |(\xi,\eta)| \leq 8$, we observe that $w^{z,t}$ vanishes unless $t$ is in the set
$$ M:= \bigcup_{j=1}^J [2^{k_j-33} , 2^{k_j+33}].$$
We may thus restrict the region of  $t$-integration in~\eqref{E:K_Pi} to $M$.
Further, we may interpret the inner integral in~\eqref{E:K_Pi} as the integral of the Fourier transform of the function 
\begin{equation*}
(y_0,y_1,y_2,y_3,y_4) \mapsto
\end{equation*}
\begin{equation*}w^{z,t}_{(t)}(y_0+x_0+x_1,y_1+x_0+x_1)h_{(z^{-1}t)}(y_2+x_2)
g_{(t)}(y_3+x_3^0) 
g_{(t)}(y_4+x_3^1)   
\end{equation*}
over the hyperplane
$$
\{(-\xi,-\eta,-\xi-\eta,\xi,\eta):~\xi \in {\mathbb R}, ~\eta \in{\mathbb R}\}.
$$
It is therefore up to universal multiplicative constant equal to the integral of the function itself over the orthogonal complement
$$
\{(p+q-r,q-r,r,p+q,q):~p, q, r\in {\mathbb R}\}.
$$
The form $\Lambda_{D_1,K^{(z)}}((f_s)_{s\in S})$ can then be rewritten as
\begin{equation}\label{E:form}
\int_M \int_{{\mathbb R}^8}  \Big[\prod_{s\in S} f_s(\Pi_s x)\Big] 
w^{z,t}_{(t)}(x_0+x_1+p+q-r, x_0+x_1+q-r) 
\end{equation}
\begin{equation*}
\times h_{(z^{-1}t)}(x_2+r) g_{(t)}(x_3^0+p+q)
g_{(t)}(x_3^1+q) 
\,dx dp dq dr \frac{dt}{t}.
\end{equation*}
 We write the integral in $x_2$ as the innermost and use the Cauchy-Schwarz inequality in the remaining variables. This bounds~\eqref{E:form} by the geometric mean of
\begin{equation}\label{E:second-term}
\int_{M} \int_{{\mathbb R}^7} \Big[\prod_{i=0,1} |f_{2}(x_0,x_1,x_3^i)|^2 \Big ]  
|w^{z,t}_{(t)}(x_0+x_1+p+q-r, x_0+x_1+q-r)| 
\end{equation}
\begin{equation*}
\times g_{(t)}(x_3^0+p+q)
g_{(t)}(x_3^1+q) 
 \,dx_0 dx_1 dx_3^0 dx_3^1 dp dq dr \frac{dt}{t}
\end{equation*}
and
\begin{equation*}
\int_{0}^\infty \int_{{\mathbb R}^7} 
\Big[
\int_{{\mathbb R}} \Big [ \prod_{i=0,1}f_0(x_3^i,x_1,x_2)f_1(x_0,x_3^i,x_2) \Big ] 
h_{(z^{-1}t)}(x_2+r) \,dx_2\Big]^2 \end{equation*}
\begin{equation*}
\times |w^{z,t}_{(t)}(x_0+x_1+p+q-r, x_0+x_1+q-r)| 
\end{equation*}
\begin{equation}\label{E:first-term}
\times g_{(t)}(x_3^0+p+q)
g_{(t)}(x_3^1+q) 
\,dx_0 dx_1 dx_3^0 dx_3^1 dp dq dr \frac{dt}{t}.
\end{equation}

In order to bound~\eqref{E:second-term} and~\eqref{E:first-term}, we prove a pointwise estimate for $w^{z,t}$. We first claim
\begin{equation}\label{E:first-estimate}
|w^{z,t}(u,v)| 
\lesssim z^\lambda.
\end{equation}
To verify the claim, we observe that
since $\widehat{K}$ vanishes on the diagonal $\xi+\eta=0$, the function $\widehat{K_{(t^{-1})} \ast \phi}$ has the same property. 
Therefore
\begin{equation}\label{E:der-est}
    |\widehat{K_{(t^{-1})} \ast \phi}(\xi,\eta)|
=|\widehat{K_{(t^{-1})} \ast \phi}(\xi,\eta)-\widehat{K_{(t^{-1})} \ast \phi}((\xi-\eta)/2,-(\xi-\eta)/2)|
\end{equation}
\begin{equation*}
=\Big|\int_{{\mathbb R}^2} K_{(t^{-1})} \ast \phi(u,v) e^{-\pi i(\xi-\eta)(u-v)} (e^{-\pi i(\xi+\eta)(u+v)}-1) \,du dv\Big|
\end{equation*}
\begin{equation*}
\lesssim \int_{{\mathbb R}^2} |K_{(t^{-1})} \ast \phi(u,v)| \min\{|\xi+\eta||u+v|,1\}\,du dv
\end{equation*}
\begin{equation*}
\leq |\xi+\eta|^{\lambda-1} \int_{{\mathbb R}^2} |K_{(t^{-1})} \ast \phi(u,v)| ~ |u+v|^{\lambda-1}\,du dv,
\end{equation*}
as $\lambda-1 \in (0,1)$.
We observe that 
\begin{equation}\label{E:kt}
|K_{(t^{-1})} \ast \phi(u,v)| \lesssim 2^{\lambda k}(1+2^k|u+v|)^{-4} (1+|u-v|)^{-4} +  (1+|u+v|)^{-4} (1+|u-v|)^{-4},
\end{equation}
thanks to the derivative estimates on $\phi$, to the support properties of $\widehat{\phi}$ and $\widehat{\Phi_j}$ and to~\eqref{E:phi-lambda3/2}.
Therefore,
\begin{equation*}
\int_{{\mathbb R}^2} |K_{(t^{-1})} \ast \phi(u,v)|~ |u+v|^{\lambda-1}\,du dv
\end{equation*}
\begin{equation*}
\lesssim 2^{k} \int_{{\mathbb R}^2} (1+2^k|u+v|)^{\lambda-5} (1+|u-v|)^{-4}\, du dv
+ \int_{{\mathbb R}^2} (1+|u+v|)^{\lambda-5} (1+|u-v|)^{-4}\, du dv
\lesssim 1.
\end{equation*}
 Combining this with~\eqref{E:der-est} and passing to $w^{z,t}$, we thus obtain
\[
|\widehat{w^{z,t}}(\xi,\eta)|
\lesssim z^{\lambda-1}. 
\]
Estimating the Fourier inversion formula by $L^1 \rightarrow L^\infty$ bounds, inequality~\eqref{E:first-estimate} follows.

We note that the right-hand side of~\eqref{E:first-estimate} has the desired decay as $z$ tends to $0$, however, it does not have a good behavior with respect to $(u,v)$. We therefore derive a yet another estimate for $w^{z,t}$ in which the right-hand side possesses merely $L^1$ scaling in $z$ but decays sufficiently fast as $|(u,v)|$ tends to infinity. We set 
\[
F(u,v)=\omega_{(z^{-1})}((u+v)/2) \theta((u-v)/2).
\]
By~\eqref{E:def-wst}, we have
$w^{z,t}=K_{(t^{-1})} \ast \phi \ast F$. 
Recall that the functions $\widehat{\omega}$ and $\widehat{\theta}$ are supported in $[-2,2]$ and have derivatives up to order $8$ bounded by $\lesssim 1$. 
Using~\eqref{E:kt}, we therefore obtain
\begin{equation}\label{E:I}
|w^{z,t}(u,v)| \lesssim 2^{\lambda k}(1+2^k|u+v|)^{-4} (1+|u-v|)^{-4}
+z(1+z|u+v|)^{-4} (1+|u-v|)^{-4} \quad \text{if } 2^k \leq z
\end{equation}
and
\begin{equation}\label{E:II}
|w^{z,t}(u,v)| \lesssim z(1+z|u+v|)^{-4} (1+|u-v|)^{-4} \quad \text{if } z \leq 2^k.
\end{equation}

Finally, we write $|w^{z,t}|=|w^{z,t}|^{\frac{\lambda-1}{2\lambda}} |w^{z,t}|^{\frac{\lambda+1}{2\lambda}}$ and use the estimate~\eqref{E:first-estimate} for the first factor and the estimates~\eqref{E:I} and~\eqref{E:II} for the second factor. This yields the desired bounds
\begin{equation}\label{E:wzt-pointwise}
|w^{z,t}(u,v)| \lesssim z^{\frac{(\lambda-1)^2}{2\lambda}} [z(1+z|u+v|)^{-2-\frac{2}{\lambda}}+2^k(1+2^k|u+v|)^{-2-\frac{2}{\lambda}}] (1+|u-v|)^{-2-\frac{2}{\lambda}}  
\end{equation}
if  $2^k \leq z$, and
\begin{equation}\label{E:wzt-pointwise-2}
|w^{z,t}(u,v)| \lesssim z^{\frac{(\lambda-1)^2}{2\lambda}} z(1+z|u+v|)^{-2-\frac{2}{\lambda}} (1+|u-v|)^{-2-\frac{2}{\lambda}} \quad \text{if } z \leq 2^k.
\end{equation}

Having inequalities~\eqref{E:wzt-pointwise} and~\eqref{E:wzt-pointwise-2} at our disposal, we proceed to bound the term~\eqref{E:second-term}.
